package com.bank.payrollsum;

import java.util.*;
import java.util.logging.*;

public class ParallelSumDemo {
    private static final Logger log = Logger.getLogger("PayrollSum");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>();
        for (int i = 0; i < 5; i++) staff.add(new Employee("E" + i, 100000 + i));
        PayrollSumService service = new PayrollSumService();

        log.info(() -> "sequential sum: " + service.sumSequential(staff));
        log.info(() -> "parallel sum  : " + service.sumParallel(staff));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    double getSalary() { return salary; }
}

// ─── Would be in service/PayrollSumService.java ───
class PayrollSumService {
    double sumSequential(List<Employee> staff) {
        return staff.stream().mapToDouble(Employee::getSalary).sum();
    }
    double sumParallel(List<Employee> staff) {
        // parallel: splits across common ForkJoinPool; worthwhile only for large n
        return staff.parallelStream().mapToDouble(Employee::getSalary).sum();
    }
}
